const bg=Color(0xFFF5F9F7), white=Colors.white, ink=Color(0xFF172326), muted=Color(0xFF77858A), line=Color(0xFFE8EFEC), green=Color(0xFF079B7B), darkGreen=Color(0xFF08765F), mint=Color(0xFFE4F5EF), soft=Color(0xFFF0F6F3);
