class MapPainter extends CustomPainter{@override void paint(Canvas canvas,Size s){canvas.drawRect(Offset.zero&s,Paint()..color=const Color(0xFFE8EFEB));final sea=Path()..moveTo(0,s.height*.58)..cubicTo(s.width*.3,s.height*.4,s.width*.4,s.height*.75,s.width*.6,s.height*.6)..cubicTo(s.width*.8,s.height*.5,s.width*.9,s.height*.7,s.width,s.height*.58)..lineTo(s.width,s.height)..lineTo(0,s.height)..close();canvas.drawPath(sea,Paint()..color=const Color(0xFFD8EAE8));for(int i=0;i<7;i++){final p=Path()..moveTo(-20,20+i*39)..cubicTo(s.width*.3,i*35,s.width*.6,45+i*33,s.width+20,15+i*38);canvas.drawPath(p,Paint()..color=white..strokeWidth:7..style=PaintingStyle.stroke);canvas.drawPath(p,Paint()..color=const Color(0xFFD0DCD7)..strokeWidth:1.5..style=PaintingStyle.stroke);}}@override bool shouldRepaint(covariant CustomPainter old)=>false;}

